hickness=1 return b end local function MC(b,r)Instance.new("UICorner",b).CornerRadius=UDim.new(0,r)end local MN=MB(F,"–",0,0,11,11,Color3.fromRGB(30,30,40))MN.Position=UDim2.new(1,-32*SM,0,4*SM)MN.TextColor3=Color3.fromRGB(130,170,255)MN.TextSize=9*SM MC(MN,3)local CL=MB(F,"×",0,0,11,11,Color3.fromRGB(30,30,40))CL.Position=UDim2.new(1,-18*SM,0,4*SM)CL.TextColor3=Color3.fromRGB(255,80,80)CL.TextSize=10*SM MC(CL,3)CL.MouseButton1Click:Connect(function()G.Enabled=false end)local CH=Instance.new("Frame",F)CH.Name="ContentHolder"CH.BackgroundTransparency=1 CH.Position=UDim2.new(0,0,0,22*SM)CH.Size=UDim2.new(1,0,1,-22*SM)local mn=false MN.MouseButton1Click:Connect(function()mn=not mn if mn then F.Size=UDim2.new(0,110*SM,0,19*SM)CH.Visible=false MN.Text="+"else F.Size=UDim2.new(0,110*SM,0,100*SM)CH.Visible=true MN.Text="–"end end)local yP=2 getgenv().CH=CH getgenv().MF=F getgenv().SG=G getgenv().SM=SM getgenv().MenuN=function(t)T.Text=t end getgenv().AddBtn=function(n,c)local b=MB(CH,n,7,yP,96,16)yP=yP+19 if c then b.MouseButton1Click:Connect(c)end return b end getgenv().Panel=function(title,w,h)local pan=Instance.new("Frame")pan.Name="Panel_"..title pan.Size=UDim2.new(0,w or 140,0,h or 80)pan.Position=UDim2.new(.5,80,.5,-40)pan.BackgroundColor3=Color3.fromRGB(15,15,20)pan.BorderSizePixel=0 pan.Visible=false pan.Active=true pan.Draggable=true pan.Parent=G Instance.new("UICorner",pan).CornerRadius=UDim.new(0,7)local pst=Instance.new("UIStroke",pan)pst.Color=Color3.fromRGB(35,35,45)pst.Thickness=1 local ttl=Instance.new("TextLabel",pan)ttl.BackgroundTransparency=1 ttl.Position=UDim2.new(0,5*SM,0,4*SM)ttl.Size=UDim2.new(0,80*SM,0,12*SM)ttl.Font=Enum.Font.GothamBold ttl.Text=title ttl.TextColor3=Color3.fromRGB(255,255,255)ttl.TextSize=7*SM ttl.TextXAlignment=Enum.TextXAlignment.Left local cls=Instance.new("TextButton",pan)cls.BackgroundColor3=Color3.fromRGB(30,30,40)cls.Position=UDim2.new(1,-18*SM,0,4*SM)cls.Size=UDim2.new(0,11*SM,0,11*SM)cls.Font=Enum.Font.GothamBold cls.Text